  slide.addText(String(num).padStart(2, '0'), { x: 12.22, y: 6.98, w: 0.5, h: 0.25, fontSize: 9, color: C.muted, bold: true, align: 'right', margin: 0 });
}

function chip(slide, text, x, y, w, color, fill) {
  slide.addShape(pptx.ShapeType.roundRect, { x, y, w, h: 0.31, rectRadius: 0.06, fill: { color: fill || 'FFFFFF', transparency: fill ? 0 : 100 }, line: { color, width: 1.0 } });
  slide.addText(text, { x: x + 0.08, y: y + 0.065, w: w - 0.16, h: 0.14, fontSize: 7.8, color, bold: true, align: 'center', margin: 0 });
}

function addCard(slide, x, y, w, h, fill='FFFFFF', line=C.line, shadow=true) {
  slide.addShape(pptx.ShapeType.roundRect, {
    x, y, w, h, rectRadius: 0.08,
    fill: { color: fill },
    line: { color: line, width: 0.8 },
    shadow: shadow ? { type: 'outer', color: '000000', opacity: 0.09, blur: 2, angle: 45, offset: 1 } : undefined
  });
}

function addHeaderPill(slide, text, x, y, color, fill) {
  slide.addShape(pptx.ShapeType.roundRect, { x, y, w: 1.7, h: 0.35, rectRadius: 0.08, fill: { color: fill }, line: { color: fill } });
  slide.addText(text, { x, y: y + 0.09, w: 1.7, h: 0.12, fontSize: 8.5, color, bold: true, align: 'center', margin: 0 });
}

function bulletList(slide, items, x, y, w, h, fontSize=12, color=C.ink) {
  const runs = [];
  items.forEach((item, i) => runs.push({ text: item, options: { bullet: { indent: 11 }, hanging: 3, breakLine: i < items.length - 1 } }));
  slide.addText(runs, { x, y, w, h, fontSize, color, breakLine: false, fit: 'shrink', paraSpaceAfterPt: 6, margin: 0.04 });
}

function metric(slide, value, label, x, y, color=C.teal) {
  slide.addText(value, { x, y, w: 1.45, h: 0.45, fontSize: 25, bold: true, color, align: 'center', margin: 0 });
  slide.addText(label, { x: x - 0.05, y: y + 0.46, w: 1.55, h: 0.28, fontSize: 7.5, color: C.slate, align: 'center', margin: 0, fit: 'shrink' });
}

